import { Client } from './vendor-sdk.js';

// The SDK reads its credential from the environment; it is never hardcoded here.
export function createClient() {
  return new Client({
    apiKey: process.env.SERVICE_API_KEY,
    baseUrl: process.env.SERVICE_BASE_URL ?? 'https://api.example.internal',
    timeoutMs: 10_000,
  });
}

import os

from vendor_sdk import Client


def create_client() -> Client:
    """Build the SDK client from environment configuration."""
    return Client(
        api_key=os.environ["SERVICE_API_KEY"],
        base_url=os.environ.get("SERVICE_BASE_URL", "https://api.example.internal"),
        timeout=10,
    )

resource "aws_instance" "web" {
  ami           = var.ami_id
  instance_type = "t3.micro"

  tags = {
    Name        = "web-server"
    Environment = var.environment
  }
}

variable "ami_id" {
  type        = string
  description = "AMI id for the web server"
}

pid_file = "/run/vault-agent/pidfile"
exit_after_auth = false

vault {
  address = "https://vault.example.internal:8200"
  ca_cert = "/etc/vault-agent/ca.pem"
  retry {
    num_retries = 5
  }
}

auto_auth {
  method "approle" {
    mount_path = "auth/approle"
    config = {
      role_id_file_path                   = "/etc/vault-agent/role-id"
      secret_id_file_path                 = "/etc/vault-agent/secret-id"
      remove_secret_id_file_after_reading = true
    }
  }

  sink "file" {
    config = {
      path = "/run/vault-agent/token"
      mode = 0640
    }
  }
}

cache {
  use_auto_auth_token = true
}

listener "unix" {
  address     = "/run/vault-agent/agent.sock"
  tls_disable = true
}

# Renders DB credentials for the nightly reports job.
template {
  destination = "/run/reports/db.env"
  perms       = "0600"
  command     = "systemctl reload reports-exporter"
  contents    = <<-EOT
    {{- with secret "database/creds/reports-readonly" -}}
    REPORTS_DB_USER={{ .Data.username }}
    REPORTS_DB_PASSWORD={{ .Data.password }}
    {{- end }}
  EOT
}

template {
  destination = "/run/reports/smtp.json"
  perms       = "0600"
  contents    = <<-EOT
    {{ with secret "kv/data/reports/smtp" }}{"user":"{{ .Data.data.user }}","password":"{{ .Data.data.password }}"}{{ end }}
  EOT
}

telemetry {
  prometheus_retention_time = "30s"
  disable_hostname          = true
}

{
  "name": "geo-tiles (Rust + PostGIS)",
  "image": "mcr.microsoft.com/devcontainers/rust:1-bookworm@sha256:13bb6664aa81e6dae36d609d85d9983af84adddd1a0a6bd7db7834262811a488",
  "features": {
    "ghcr.io/devcontainers/features/node:1": { "version": "20" },
    "ghcr.io/devcontainers/features/docker-outside-of-docker:1": {},
    "ghcr.io/devcontainers/features/aws-cli:1": {}
  },
  "forwardPorts": [3000, 5432, 8080],
  "portsAttributes": {
    "3000": { "label": "tile viewer" },
    "5432": { "label": "postgis", "onAutoForward": "silent" }
  },
  "containerEnv": {
    "RUST_LOG": "geo_tiles=debug,tower_http=info",
    "DATABASE_HOST": "localhost",
    "DATABASE_USER": "tiles",
    "MAPBOX_PUBLIC_STYLE": "mapbox://styles/example-org/clx0example",
    "TILE_CACHE_BUCKET": "example-tiles-dev"
  },
  "remoteEnv": {
    "DATABASE_PASSWORD": "${localEnv:GEO_TILES_DB_PASSWORD}",
    "TILE_SIGNING_SECRET": "${localEnv:GEO_TILES_SIGNING_SECRET}",
    "AWS_PROFILE": "geo-tiles-dev"
  },
  "secrets": {
    "GEO_TILES_DB_PASSWORD": {
      "description": "Password for the local PostGIS container (any value works locally)."
    },
    "GEO_TILES_SIGNING_SECRET": {
      "description": "HMAC secret used to sign tile URLs; generate with `openssl rand -hex 32`."
    }
  },
  "mounts": [
    "source=${localEnv:HOME}/.aws,target=/home/vscode/.aws,type=bind,readonly"
  ],
  "postCreateCommand": "cargo fetch && npm ci --prefix viewer",
  "customizations": {
    "vscode": {
      "extensions": [
        "rust-lang.rust-analyzer",
        "tamasfe.even-better-toml",
        "ms-ossdata.vscode-pgsql"
      ],
      "settings": {
        "rust-analyzer.check.command": "clippy"
      }
    }
  }
}

