// Package httpmw는 내부 API 게이트웨이에서 쓰는 HTTP 미들웨어 모음입니다.
package httpmw

import (
	"context"
	"crypto/subtle"
	"errors"
	"log/slog"
	"net/http"
	"strings"
)

type ctxKey struct{}

// TokenVerifier는 Authorization 헤더에서 꺼낸 bearer 토큰을 검증합니다.
// 실제 검증은 introspection 서비스(auth.internal:8443)가 담당합니다.
type TokenVerifier interface {
	Verify(ctx context.Context, token string) (Principal, error)
}

type Principal struct {
	Subject  string
	TenantID string
	Scopes   []string
}

var ErrMissingCredential = errors.New("httpmw: missing or malformed Authorization header")

// RequireBearer는 "Authorization: Bearer <token>" 형식만 허용합니다.
// 토큰 값은 절대 로그에 남기지 않습니다 — 길이만 기록합니다.
func RequireBearer(v TokenVerifier, log *slog.Logger) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			raw := r.Header.Get("Authorization")
			scheme, token, ok := strings.Cut(raw, " ")
			if !ok || !strings.EqualFold(scheme, "Bearer") || token == "" {
				log.Warn("인증 헤더 없음", "path", r.URL.Path, "request_id", r.Header.Get("X-Request-Id"))
				w.Header().Set("WWW-Authenticate", `Bearer realm="gateway", error="invalid_request"`)
				http.Error(w, ErrMissingCredential.Error(), http.StatusUnauthorized)
				return
			}
			p, err := v.Verify(r.Context(), token)
			if err != nil {
				log.Info("토큰 검증 실패", "token_len", len(token), "err", err)
				w.Header().Set("WWW-Authenticate", `Bearer realm="gateway", error="invalid_token"`)
				http.Error(w, "unauthorized", http.StatusUnauthorized)
				return
			}
			next.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), ctxKey{}, p)))
		})
	}
}

// StaticKeyVerifier는 로컬 개발용입니다. 키는 환경 변수 GATEWAY_DEV_KEY에서 주입됩니다.
type StaticKeyVerifier struct{ Key []byte }

func (s StaticKeyVerifier) Verify(_ context.Context, token string) (Principal, error) {
	if len(s.Key) == 0 || subtle.ConstantTimeCompare(s.Key, []byte(token)) != 1 {
		return Principal{}, errors.New("key mismatch")
	}
	return Principal{Subject: "dev-user", TenantID: "00000000-0000-0000-0000-000000000000"}, nil
}

func FromContext(ctx context.Context) (Principal, bool) {
	p, ok := ctx.Value(ctxKey{}).(Principal)
	return p, ok
}

//! Runtime configuration for the telemetry ingest worker.
//!
//! Loaded from `ingest.toml` and overridden by `INGEST_*` environment
//! variables. Sensitive fields are wrapped in `SecretString` so they never
//! show up in `Debug` output or panic messages.

use std::{net::SocketAddr, path::PathBuf, time::Duration};

use secrecy::{ExposeSecret, SecretString};
use serde::Deserialize;

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct IngestConfig {
    pub listen: SocketAddr,
    pub queue: QueueConfig,
    pub object_store: ObjectStoreConfig,
    #[serde(with = "humantime_serde", default = "default_flush")]
    pub flush_interval: Duration,
}

#[derive(Debug, Deserialize)]
pub struct QueueConfig {
    /// e.g. `nats://queue.internal:4222`
    pub url: String,
    pub subject: String,
    /// Path to an nkey seed file mounted by the orchestrator.
    pub credentials_file: Option<PathBuf>,
}

#[derive(Debug, Deserialize)]
pub struct ObjectStoreConfig {
    pub bucket: String,
    pub region: String,
    pub access_key_id: Option<String>,
    /// Never logged. `Debug` prints `Secret([REDACTED alloc::string::String])`.
    pub secret_access_key: Option<SecretString>,
    #[serde(default)]
    pub path_style: bool,
}

fn default_flush() -> Duration {
    Duration::from_secs(5)
}

impl ObjectStoreConfig {
    /// Returns true when static credentials are configured; otherwise the
    /// worker falls back to the instance role / web identity token.
    pub fn has_static_credentials(&self) -> bool {
        self.access_key_id.is_some()
            && self
                .secret_access_key
                .as_ref()
                .is_some_and(|s| !s.expose_secret().is_empty())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const SAMPLE: &str = r#"
        listen = "0.0.0.0:9464"
        flush_interval = "2s"

        [queue]
        url = "nats://127.0.0.1:4222"
        subject = "telemetry.v1.raw"

        [object_store]
        bucket = "ingest-staging"
        region = "eu-central-1"
        secret_access_key = "placeholder-not-a-key"
    "#;

    #[test]
    fn debug_output_hides_secret() {
        let cfg: IngestConfig = toml::from_str(SAMPLE).unwrap();
        let dbg = format!("{cfg:?}");
        assert!(!dbg.contains("placeholder-not-a-key"));
        assert!(!cfg.object_store.has_static_credentials());
    }
}

package com.example.payments.config;

import java.time.Duration;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.web.client.RestTemplateBuilder;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.http.HttpHeaders;
import org.springframework.web.client.RestTemplate;

/**
 * Konfiguration für den Zahlungs-Gateway-Client.
 *
 * <p>Alle sensiblen Werte (API-Schlüssel, Webhook-Signaturgeheimnis) kommen
 * aus dem Vault-Pfad {@code secret/data/payments/gateway} und werden über
 * Spring Cloud Vault als Properties bereitgestellt. Niemals in
 * {@code application.yml} eintragen!
 */
@Configuration
public class GatewayClientConfig {

    // Basis-URL des Anbieters, pro Umgebung unterschiedlich
    @Value("${payments.gateway.base-url:https://sandbox.payments.example.net/v2}")
    private String baseUrl;

    // API-Schlüssel – kein Default, damit der Start ohne Vault fehlschlägt
    @Value("${payments.gateway.api-key}")
    private String apiKey;

    @Value("${payments.gateway.webhook-secret}")
    private String webhookSecret;

    @Value("${payments.gateway.merchant-id:MERCHANT-DE-0042}")
    private String merchantId;

    @Value("${payments.gateway.timeout:PT8S}")
    private Duration timeout;

    @Bean
    public RestTemplate gatewayRestTemplate(RestTemplateBuilder builder) {
        return builder
                .rootUri(baseUrl)
                .setConnectTimeout(Duration.ofSeconds(2))
                .setReadTimeout(timeout)
                // Der Schlüssel wird nur als Header gesetzt, nie geloggt
                .defaultHeader(HttpHeaders.AUTHORIZATION, "Bearer " + apiKey)
                .defaultHeader("X-Merchant-Id", merchantId)
                .build();
    }

    @Bean
    public WebhookSignatureVerifier webhookSignatureVerifier() {
        // HMAC-SHA256 über den Rohtext des Requests
        return new WebhookSignatureVerifier(webhookSecret, "X-Signature-256");
    }

    @Override
    public String toString() {
        return "GatewayClientConfig{baseUrl=" + baseUrl + ", merchantId=" + merchantId
                + ", apiKey=********, webhookSecret=********}";
    }
}

package com.example.fieldtrack.di

import com.example.fieldtrack.BuildConfig
import com.example.fieldtrack.auth.SessionStore
import dagger.Module
import dagger.Provides
import dagger.hilt.InstallIn
import dagger.hilt.components.SingletonComponent
import okhttp3.CertificatePinner
import okhttp3.Interceptor
import okhttp3.OkHttpClient
import okhttp3.logging.HttpLoggingInterceptor
import retrofit2.Retrofit
import retrofit2.converter.moshi.MoshiConverterFactory
import javax.inject.Singleton

/**
 * BuildConfig fields are injected from gradle.properties / CI env:
 *   buildConfigField("String", "API_BASE_URL", "\"${project.findProperty("fieldtrack.apiBaseUrl")}\"")
 *   buildConfigField("String", "MAPS_API_KEY", "\"${System.getenv("FIELDTRACK_MAPS_KEY") ?: ""}\"")
 * Local builds get an empty maps key and fall back to the offline tile cache.
 */
@Module
@InstallIn(SingletonComponent::class)
object NetworkModule {

    private const val PIN_HOST = "api.fieldtrack.example.com"

    // SPKI pins (base64 SHA-256 of the public key) — public values, rotated with the cert.
    private val pinner = CertificatePinner.Builder()
        .add(PIN_HOST, "sha256/kPg6LZrCj3v4E0YqvXx1zS8HbA2r5pQm9tWcN0uJfGs=")
        .add(PIN_HOST, "sha256/3mJ8QwYtRz2bN5cVx9LpK1sHdG7fA0eUo4iTq6nWyEk=")
        .build()

    @Provides
    @Singleton
    fun authInterceptor(session: SessionStore): Interceptor = Interceptor { chain ->
        val req = chain.request().newBuilder().apply {
            session.accessToken()?.let { header("Authorization", "Bearer $it") }
            header("X-App-Version", "${BuildConfig.VERSION_NAME} (${BuildConfig.VERSION_CODE})")
            header("X-Device-Id", session.installationId)
        }.build()
        chain.proceed(req)
    }

    @Provides
    @Singleton
    fun okHttp(auth: Interceptor): OkHttpClient = OkHttpClient.Builder()
        .certificatePinner(pinner)
        .addInterceptor(auth)
        .apply {
            if (BuildConfig.DEBUG) {
                addInterceptor(HttpLoggingInterceptor().apply {
                    level = HttpLoggingInterceptor.Level.HEADERS
                    redactHeader("Authorization")
                    redactHeader("Cookie")
                })
            }
        }
        .build()

    @Provides
    @Singleton
    fun retrofit(client: OkHttpClient): Retrofit = Retrofit.Builder()
        .baseUrl(BuildConfig.API_BASE_URL)
        .client(client)
        .addConverterFactory(MoshiConverterFactory.create())
        .build()

    fun mapsKeyOrNull(): String? = BuildConfig.MAPS_API_KEY.takeIf { it.isNotBlank() }
}

import Foundation
import Security

/// キーチェーンへの薄いラッパー。
/// リフレッシュトークンや API キーなどの機密値はここ以外に保存しないこと。
/// UserDefaults への保存はレビューで却下されます。
public struct KeychainStore {
    public enum Key: String, CaseIterable {
        case refreshToken = "com.example.notes.refresh-token"
        case deviceSecret = "com.example.notes.device-secret"
        case syncPassword = "com.example.notes.sync-password"
    }

    public enum Failure: Error, Equatable {
        case unexpectedStatus(OSStatus)
        case invalidData
    }

    private let service: String
    private let accessGroup: String?

    // アクセスグループはチーム ID 付き(App Group と共有するため)
    public init(service: String = "com.example.notes", accessGroup: String? = "ABCDE12345.com.example.shared") {
        self.service = service
        self.accessGroup = accessGroup
    }

    private func baseQuery(_ key: Key) -> [String: Any] {
        var q: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: service,
            kSecAttrAccount as String: key.rawValue,
        ]
        if let group = accessGroup { q[kSecAttrAccessGroup as String] = group }
        return q
    }

    /// 値を保存(既存があれば上書き)。端末ロック解除後のみ読み取り可能。
    public func set(_ value: String, for key: Key) throws {
        guard let data = value.data(using: .utf8) else { throw Failure.invalidData }
        let query = baseQuery(key)
        let attrs: [String: Any] = [
            kSecValueData as String: data,
            kSecAttrAccessible as String: kSecAttrAccessibleAfterFirstUnlockThisDeviceOnly,
        ]
        var status = SecItemUpdate(query as CFDictionary, attrs as CFDictionary)
        if status == errSecItemNotFound {
            status = SecItemAdd(query.merging(attrs) { $1 } as CFDictionary, nil)
        }
        guard status == errSecSuccess else { throw Failure.unexpectedStatus(status) }
    }

    public func string(for key: Key) throws -> String? {
        var query = baseQuery(key)
        query[kSecReturnData as String] = true
        query[kSecMatchLimit as String] = kSecMatchLimitOne
        var item: CFTypeRef?
        let status = SecItemCopyMatching(query as CFDictionary, &item)
        if status == errSecItemNotFound { return nil }
        guard status == errSecSuccess, let data = item as? Data else {
            throw Failure.unexpectedStatus(status)
        }
        return String(data: data, encoding: .utf8)
    }

    /// サインアウト時に全キーを削除
    public func wipe() {
        Key.allCases.forEach { SecItemDelete(baseQuery($0) as CFDictionary) }
    }
}

using System.ComponentModel.DataAnnotations;
using Microsoft.Extensions.Options;

namespace Inventory.Api.Options;

/// <summary>
/// Bound from the "SearchIndex" section. In production the ApiKey comes from
/// Azure Key Vault reference "@Microsoft.KeyVault(SecretUri=https://kv-inventory-prod.vault.azure.net/secrets/search-admin-key/)";
/// locally use `dotnet user-secrets set "SearchIndex:ApiKey" "<your-api-key>"`.
/// </summary>
public sealed class SearchIndexOptions
{
    public const string SectionName = "SearchIndex";

    [Required, Url]
    public string Endpoint { get; init; } = "https://search-inventory-dev.example.net";

    [Required]
    public string IndexName { get; init; } = "sku-catalog-v7";

    /// <summary>Admin or query key. Never serialized to diagnostics.</summary>
    [Required(AllowEmptyStrings = false)]
    public string ApiKey { get; init; } = string.Empty;

    [Range(1, 1000)]
    public int BatchSize { get; init; } = 250;

    public bool UseManagedIdentity { get; init; }

    public override string ToString() =>
        $"SearchIndexOptions {{ Endpoint = {Endpoint}, IndexName = {IndexName}, ApiKey = [REDACTED], BatchSize = {BatchSize} }}";
}

public sealed class SearchIndexOptionsValidator : IValidateOptions<SearchIndexOptions>
{
    public ValidateOptionsResult Validate(string? name, SearchIndexOptions o)
    {
        if (o.UseManagedIdentity)
            return ValidateOptionsResult.Success; // token acquired via DefaultAzureCredential

        if (string.IsNullOrWhiteSpace(o.ApiKey) || o.ApiKey is "changeme" or "REPLACE_ME")
            return ValidateOptionsResult.Fail("SearchIndex:ApiKey must be supplied when managed identity is disabled.");

        return ValidateOptionsResult.Success;
    }
}

public static class SearchIndexServiceCollectionExtensions
{
    public static IServiceCollection AddSearchIndex(this IServiceCollection services, IConfiguration config)
    {
        services.AddOptions<SearchIndexOptions>()
            .Bind(config.GetSection(SearchIndexOptions.SectionName))
            .ValidateDataAnnotations()
            .ValidateOnStart();
        services.AddSingleton<IValidateOptions<SearchIndexOptions>, SearchIndexOptionsValidator>();
        return services;
    }
}

import { useCallback, useContext, useEffect, useRef, useState } from "react";
import { AuthContext } from "../auth/AuthProvider";

const API_BASE = import.meta.env.VITE_API_BASE_URL ?? "http://localhost:8787";

export interface QueryState<T> {
  data: T | undefined;
  error: Error | undefined;
  loading: boolean;
  refetch: () => void;
}

/**
 * Fetches JSON from the analytics API with the current session's access token.
 * The token is held in memory by AuthProvider (never localStorage) and is
 * refreshed silently via the httpOnly refresh cookie on a 401.
 */
export function useAuthedQuery<T>(path: string, params?: Record<string, string>): QueryState<T> {
  const { getAccessToken, refresh, signOut } = useContext(AuthContext);
  const [state, setState] = useState<Omit<QueryState<T>, "refetch">>({
    data: undefined,
    error: undefined,
    loading: true,
  });
  const [nonce, setNonce] = useState(0);
  const abortRef = useRef<AbortController | null>(null);

  const refetch = useCallback(() => setNonce((n) => n + 1), []);
  const qs = params ? `?${new URLSearchParams(params).toString()}` : "";

  useEffect(() => {
    abortRef.current?.abort();
    const ctrl = new AbortController();
    abortRef.current = ctrl;

    const run = async (retried = false): Promise<void> => {
      const token = await getAccessToken();
      const res = await fetch(`${API_BASE}${path}${qs}`, {
        signal: ctrl.signal,
        credentials: "include",
        headers: {
          Accept: "application/json",
          ...(token ? { Authorization: `Bearer ${token}` } : {}),
